// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;

import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Tests {@link TripleStore#approximatePredicateStatementCounts}: a per-predicate statement estimate cheap enough to
 * weigh every predicate before the parallel adjacency build cuts its scan ranges.
 */
class LmdbApproximatePredicateCountsTest {

	private static final long[] PREDICATES = { 10, 20, 30, 40, 50 };
	private static final int HEAVY_INDEX = 2;
	private static final int HEAVY_STATEMENTS = 20_000;
	private static final int LIGHT_STATEMENTS = 200;

	@TempDir
	File dataDir;

	private TripleStore tripleStore;

	@AfterEach
	void tearDown() throws Exception {
		if (tripleStore != null) {
			tripleStore.close();
		}
	}

	@Test
	void estimatesTrackTheRealPerPredicateDistribution() throws Exception {
		tripleStore = skewedStore(new LmdbStoreConfig("spoc,posc"));

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			long[] counts = tripleStore.approximatePredicateStatementCounts(txn, true, PREDICATES);

			assertThat(counts).isNotNull();
			assertThat(counts).hasSameSizeAs(PREDICATES);

			long total = HEAVY_STATEMENTS + (PREDICATES.length - 1L) * LIGHT_STATEMENTS;
			assertThat(java.util.Arrays.stream(counts).sum())
					.as("estimated total statements")
					.isCloseTo(total, org.assertj.core.data.Percentage.withPercentage(5));

			assertThat(counts[HEAVY_INDEX])
					.as("estimated statements of the heavy predicate")
					.isCloseTo(HEAVY_STATEMENTS, org.assertj.core.data.Percentage.withPercentage(25));

			for (int i = 0; i < counts.length; i++) {
				if (i != HEAVY_INDEX) {
					assertThat(counts[i])
							.as("estimated statements of light predicate " + PREDICATES[i])
							.isLessThan(counts[HEAVY_INDEX] / 10);
				}
			}
		}
	}

	@Test
	void inferredStatementSetIsWeighedSeparately() throws Exception {
		tripleStore = skewedStore(new LmdbStoreConfig("spoc,posc"));

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			long[] inferred = tripleStore.approximatePredicateStatementCounts(txn, false, PREDICATES);

			assertThat(inferred).isNotNull();
			assertThat(java.util.Arrays.stream(inferred).sum())
					.as("the inferred statement set is empty in this fixture")
					.isZero();
		}
	}

	@Test
	void noEstimateWithoutThePageCardinalityEstimator() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		config.setPageCardinalityEstimator(false);
		tripleStore = skewedStore(config);

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			assertThat(tripleStore.approximatePredicateStatementCounts(txn, true, PREDICATES)).isNull();
		}
	}

	@Test
	void noEstimateWithoutAPredicateLeadingIndex() throws Exception {
		tripleStore = skewedStore(new LmdbStoreConfig("spoc"));

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			assertThat(tripleStore.approximatePredicateStatementCounts(txn, true, PREDICATES)).isNull();
		}
	}

	@Test
	void anEmptyPredicateCatalogHasNoWeights() throws Exception {
		tripleStore = skewedStore(new LmdbStoreConfig("spoc,posc"));

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			assertThat(tripleStore.approximatePredicateStatementCounts(txn, true, new long[0])).isNull();
		}
	}

	private TripleStore skewedStore(LmdbStoreConfig config) throws Exception {
		TripleStore store = new TripleStore(dataDir, config, null);
		store.startTransaction();
		long subject = 1_000;
		for (int p = 0; p < PREDICATES.length; p++) {
			int statements = p == HEAVY_INDEX ? HEAVY_STATEMENTS : LIGHT_STATEMENTS;
			for (int i = 0; i < statements; i++) {
				store.storeTriple(subject++, PREDICATES[p], 5_000_000 + i, 1, true);
			}
		}
		store.commit();
		return store;
	}
}
